+
+/// Builder sugar: add one fresh `MockTool` per name.
+trait ToolArcAll {
+    fn tool_arc_all(self, names: &[&str]) -> Self;
+}
+
+impl<M, T, N, Mo, So> ToolArcAll for paigasus_helikon_core::LlmAgentBuilder<(), M, T, N, Mo, So> {
